import { Fluid } from './Core/Fluid';
import { initUI } from './UI';

import { IX } from './Core/Utility'

import { getImgFromURL } from '../../../../lib'

export class FluidSystem {

    public divText: HTMLElement;
    public mouse: number[];
    public pts: number[][];

    public fluid: Fluid;

    public t = 0.0;

    public vecs: number[][] = [];

    public emmiters: number[][] = [];
    public xx = 1;
    public yy = 1;

    public img: HTMLImageElement;
    public activated = false;
    public showVec = false;
    public url: string = ''

    constructor(div, divUI) {
        //   super(div)
        // super(SceneCreativeCoding);
        this.init();
        this.initUI(divUI);

        let url
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint_01.jpg'
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint_01.jpg';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint.png';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint.jpg';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint_02.jpg';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint_03.jpg';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint_04.jpg';
        // url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/Boston.jpg'
        url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/Boston_02.jpg';
        // url = '';
        this.importImg(url);
    }
    public importImg(url: string) {
        this.url = url;

        getImgFromURL(url).then((img: HTMLImageElement | void) => {
            if (!img) return;
            this.img = img;

            // console.log(img, img.width, img.height)



            // console.log(img)
            // this.img.onload = (ev) => {
            // this.update(img);


            img.onload = () => {
                // this.img = img;
                // console.log('ddd', this.img)

                //   this.ctx.canvas.width = img.width;
                //   this.ctx.canvas.height = img.height;

                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;

                if (ctx) {
                    ctx.drawImage(this.img, 0, 0, this.fluid.N, this.fluid.N);

                    const data: ImageData | undefined = ctx.getImageData(0, 0, this.fluid.N, this.fluid.N);
                    // const width = ctx.canvas.width;

                    if (data) {

                        for (let y = 0; y < this.fluid.N; ++y) {
                            for (let x = 0; x < this.fluid.N; ++x) {
                                const d = data.data[(x + (this.fluid.N * y)) * 4];
                                if (d < 200) {

                                    this.fluid.cellFixed.push([x, y]);
                                }

                            }
                        }

                    }
                    // console.log(this.fluid)

                }

            };

            this.init();
        });
    }
    public initUI(divUI) {
        initUI(divUI, this);
        //   initUI(this.divHost, this);

        this.emmiters.push([Math.floor(0.5 * this.fluid.N), Math.floor(0.5 * this.fluid.N)]);
    }
    public init() {
        this.fluid = new Fluid(0.02, 0, 0.0000001);
        this.emmiters = [];
        this.emmiters.push([Math.floor(0.5 * this.fluid.N), Math.floor(0.5 * this.fluid.N)]);
        this.activated = true;

        //   this.isStatic = false;
        //   this.start();
    }
    public render(ctx: CanvasRenderingContext2D): void {
        this.activated && this.RenderIndependentCanvas(ctx);
    }
    public RenderIndependentCanvas(ctx: CanvasRenderingContext2D) {


        for (let k = 0; k < this.emmiters.length; ++k) {
            let cx = this.emmiters[k][0];
            let cy = this.emmiters[k][1];
            // console.log('cx, cy', cx, cy)
            for (let i = -1; i <= 1; i++) {
                for (let j = -1; j <= 1; j++) {
                    // this.fluid.addDensity(cx + i, cy + j, random(50, 150));
                    // console.log((Math.random() * 100) + 50)
                    this.fluid.addDensity(cx + i, cy + j, (Math.random() * 5));
                }
            }
        }

        for (let k = 0; k < this.emmiters.length; ++k) {
            let cx = this.emmiters[k][0];
            let cy = this.emmiters[k][1];
            for (let i = 0; i < 2; i++) {
                // let angle = noise(t) * Math.PI * 2;
                // let v = p5.Vector.fromAngle(angle);
                // v.mult(0.2);
                // this.t += 0.01;
                // this.fluid.addVelocity(cx, cy, v.x, v.y);
                this.fluid.addVelocity(cx, cy, this.xx, this.yy);
                // this.fluid.addVelocity(cx, cy, 1 , 1);
            }
        }

        this.fluid.step();
        this.fluid.renderD(ctx);
        this.showVec && this.fluid.renderV(ctx);

        // if (this.img) {
        //   ctx.drawImage(this.img, 0, 0);
        // }
    }
    public mouseClick(x: number, y: number): void {
        const xx = Math.floor(x / this.fluid.SCALE);
        const yy = Math.floor(y / this.fluid.SCALE);
        this.emmiters.push([xx, yy]);
    }
    public mouseDrag(x: number, y: number) {
        const xx = Math.floor(x / this.fluid.SCALE);
        const yy = Math.floor(y / this.fluid.SCALE);
        this.fluid.cellFixed.push([xx, yy]);
    }
    public rotation(angle: number) {
        const theta = angle * Math.PI / 180;
        this.xx = Math.cos(theta);
        this.yy = Math.sin(theta);
    }
    public mouseMove(x: number, y: number) {
        const xx = Math.floor(x / this.fluid.SCALE);
        const yy = Math.floor(y / this.fluid.SCALE);
        const d = this.fluid.density[xx + yy * this.fluid.N];
        if (d) {
            this.divText.innerHTML = `${d}`;
        }
    }
    public toJson() {
        // this.fluid.toJson();

        const data = []

        for (let i = 0; i < this.fluid.N; i++) {
            for (let j = 0; j < this.fluid.N; j++) {
                let density = this.fluid.density[IX(i, j, this.fluid.N)];
                let x = i * this.fluid.SCALE;
                let y = j * this.fluid.SCALE;
                data.push({
                    x, y, density
                })
            }
        }

        // console.log(data)
        downloadJson(JSON.stringify(data));
    }
    public toPng() {
        // console.log('png');
    }
    public toObj() {
        // console.log('obj');

    }
}

const downloadJson = (collection, name = 'download',) => {
    const link = document.createElement('a');
    link.href = 'data:application/json;charset=utf-8,' + encodeURIComponent(collection);
    link.download = `${name}`;
    link.click();
};